 "content": "def transform(grid):
    """Project the color at each marked cross along its row and column.

    The four 3-valued arms remain visible. They are transparent to the
    projection from their own center and stop projections from other crosses.
    At crossings, vertical projections take precedence over horizontal ones.
    """
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    out = [row[:] for row in grid]

    # A colored center is identified by the four cardinal 3-valued arms.
    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            color = original[r][c]
            if color not in (0, 3) and all(
                original[r + dr][c + dc] == 3
                for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1))
            ):
                centers.append((r, c, color))

    # Record the arms belonging to each active source, so those do not block it.
    arms_by_center = {
        (r, c): {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        for r, c, _ in centers
    }

    def ray(r, c, color, dr, dc, horizontal):
        own_arms = arms_by_center[(r, c)]
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if original[rr][cc] == 3 and (rr, cc) not in own_arms:
                break
            # Preserve all original non-background markers and centers.
            if original[rr][cc] == 0:
                if horizontal:
                    out[rr][cc] = color
                else:
                    # Vertical projection wins at a crossing.
                    out[rr][cc] = color
            rr += dr
            cc += dc

    # Horizontal rays are laid down first; vertical rays then win overlaps.
    for r, c, color in centers:
        ray(r, c, color, 0, -1, True)
        ray(r, c, color, 0, 1, True)
    for r, c, color in centers:
        ray(r, c, color, -1, 0, False)
        ray(r, c, color, 1, 0, False)

    return out
