 "content": "def transform(grid):
    """Draw colored row/column projections from crosses, blocked by other crosses.

    A 3-valued four-arm shape is a cross. A colored center paints all blank
    cells along its row and column. A zero-centered cross deletes projections
    on its row/column, but the blank segment between its two 3 arms remains.
    Original marks are preserved. Projection ordering gives the later
    (vertical) colored line precedence where background projections coincide.
    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(src[r + dr][c + dc] == 3 for dr, dc in
                   ((-1, 0), (1, 0), (0, -1), (0, 1))):
                cells = {(r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1)}
                crosses.append((r, c, src[r][c], cells))

    def path_cells(r, c, dr, dc):
        """Yield ray locations; cross arms block unless they are this cross's."""
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            for ar, ac, _, cells in crosses:
                if (ar, ac) != (r, c) and (rr, cc) in cells:
                    return
            yield rr, cc
            rr += dr
            cc += dc

    # Colored crosses paint each ray. A zero-centered cross is not a source.
    for r, c, color, _ in crosses:
        if color in (0, 3):
            continue
        for dr, dc in ((0, -1), (0, 1), (-1, 0), (1, 0)):
            for rr, cc in path_cells(r, c, dr, dc):
                if src[rr][cc] == 0:
                    out[rr][cc] = color

    # A zero center clears incoming rays on its axes, except the segment
    # directly between its two opposite arms (the visible gap in demos).
    for r, c, color, _ in crosses:
        if color != 0:
            continue
        for cc in range(w):
            if src[r][cc] == 0 and abs(cc - c) != 1:
                out[r][cc] = 0
        for rr in range(h):
            if src[rr][c] == 0 and abs(rr - r) != 1:
                out[rr][c] = 0
    return out
",
 "cross_profile": false
}

