 "content": "def transform(grid):
    """Extend cross colors on rows and columns; 0/1 crosses erase projections.

    Crosses are centers with four cardinal neighbors of color 3. Colors >=2
    paint their row/column, preserving original nonzero marks. Rays stop at a
    different cross's 3 arm. Cross centers 0 and 1 project blank axes over
    generated paint, while their original 3 arms/centers remain intact.
    Vertical colored rays are applied after horizontal rays.
    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(src[r + dr][c + dc] == 3 for dr, dc in
                   ((-1, 0), (1, 0), (0, -1), (0, 1))):
                cells = {(r, c), (r - 1, c), (r + 1, c),
                         (r, c - 1), (r, c + 1)}
                crosses.append((r, c, src[r][c], cells))

    def cast(r, c, color, dr, dc):
        own_arms = {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            # Other 3-valued arms block a ray; pass through the source's arms.
            if src[rr][cc] == 3 and (rr, cc) not in own_arms:
                break
            if src[rr][cc] == 0:
                out[rr][cc] = color
            rr += dr
            cc += dc

    # Paint horizontal rays, then vertical rays (vertical wins overlaps).
    for r, c, color, _ in crosses:
        if color >= 2:
            cast(r, c, color, 0, -1)
            cast(r, c, color, 0, 1)
    for r, c, color, _ in crosses:
        if color >= 2:
            cast(r, c, color, -1, 0)
            cast(r, c, color, 1, 0)

    # Blank-center crosses erase generated paint along both axes, but not
    # original nonzero marks. This erasing does not terminate other rays.
    for r, c, color, _ in crosses:
        if color in (0, 1):
            for cc in range(w):
                if src[r][cc] == 0:
                    out[r][cc] = 0
            for rr in range(h):
                if src[rr][c] == 0:
                    out[rr][c] = 0
    return out
