    A cross is a cell with four cardinal neighbors of color 3. Nonzero
    centers project their color; zero-centered crosses contribute a blank
    column mask. Original nonzero cells are retained. Horizontal projections
    are applied first and vertical projections second, so vertical colors win
    at intersections; blank columns are masked last.
    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    colored = []
    blank_columns = []

    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(src[r + dr][c + dc] == 3 for dr, dc in
                   ((-1, 0), (1, 0), (0, -1), (0, 1))):
                color = src[r][c]
                if color == 0:
                    blank_columns.append(c)
                else:
                    colored.append((r, c, color))

    # Paint horizontal lines first.
    for r, c, color in colored:
        for cc in range(w):
            if src[r][cc] == 0:
