    A plus-shaped object has a center with four cardinal 3s. Each colored
    center projects along its row and column, passing through its own four
    arms but stopping at another cross's 3 arm. Original nonzero cells are
    preserved. Horizontal rays are drawn before vertical rays, so vertical
    colors win at background intersections. A zero-center cross masks its
    column, leaving that stripe blank except for original marks.
    """
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    crosses = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if all(src[r + dr][c + dc] == 3 for dr, dc in
                   ((-1, 0), (1, 0), (0, -1), (0, 1))):
                crosses.append((r, c, src[r][c]))

    blank_columns = {c for r, c, color in crosses if color == 0}
    arms_by_center = {
        (r, c): {(r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)}
        for r, c, _ in crosses
    }

    def cast(r, c, color, dr, dc):
        own_arms = arms_by_center[(r, c)]
        rr, cc = r + dr, c + dc
        while 0 <= rr < h and 0 <= cc < w:
            if src[rr][cc] == 3 and (rr, cc) not in own_arms:
                break
            if src[rr][cc] == 0:
                out[rr][cc] = color
            rr += dr
            cc += dc

    # Horizontal rays, then vertical rays for overlap precedence.
    for r, c, color in crosses:
        if color != 0:
